package com.bank.partition;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.Collectors;
import static org.assertj.core.api.Assertions.*;

class PartitionTest {

    @Test void partitionAlwaysHasTwoKeys() {
        Map<Boolean, List<String>> result = List.<String>of().stream()
            .collect(Collectors.partitioningBy(s -> true));
        assertThat(result).containsKeys(true, false);  // BOTH exist!
        assertThat(result.get(true)).isEmpty();
        assertThat(result.get(false)).isEmpty();
    }

    @Test void groupingByCanBeEmpty() {
        Map<Integer, List<String>> result = List.<String>of().stream()
            .collect(Collectors.groupingBy(String::length));
        assertThat(result).isEmpty();  // no keys at all!
    }

    @Test void partitionWithDownstream() {
        Map<Boolean, Long> counts = List.of(1, 2, 3, 4, 5).stream()
            .collect(Collectors.partitioningBy(n -> n > 3, Collectors.counting()));
        assertThat(counts.get(true)).isEqualTo(2);   // 4, 5
        assertThat(counts.get(false)).isEqualTo(3);  // 1, 2, 3
    }

    @Test void partitionForSettledVsPending() {
        record Trade(String id, boolean settled) {}
        var trades = List.of(new Trade("T1", true), new Trade("T2", false), new Trade("T3", true));
        Map<Boolean, List<Trade>> partition = trades.stream()
            .collect(Collectors.partitioningBy(Trade::settled));
        assertThat(partition.get(true)).hasSize(2);
        assertThat(partition.get(false)).hasSize(1);
    }
}
