package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import static org.assertj.core.api.Assertions.assertThat;

class PartitioningByTest {

    record Account(String id, BigDecimal balance) {}

    @Test
    void partitionGuaranteesBothKeys() {
        var accounts = List.of(
            new Account("SAV2001", new BigDecimal("1000000")),
            new Account("CUR3001", new BigDecimal("250000")),
            new Account("MIN0001", new BigDecimal("5000")));
        BigDecimal min = new BigDecimal("10000");

        Map<Boolean, List<Account>> parts = accounts.stream()
            .collect(Collectors.partitioningBy(a -> a.balance().compareTo(min) >= 0));

        assertThat(parts.get(true)).extracting(Account::id).containsExactly("SAV2001", "CUR3001");
        assertThat(parts.get(false)).extracting(Account::id).containsExactly("MIN0001");
    }
}
